import {pageSeeds} from '../cms/page-seeds.js';
import products from '../cms/products.seed.json';
import serviceBindings from '../cms/service-bindings.json';
import {applications} from '../cms/application-seeds.js';
import {seedRecords,listContent} from './cms.js';
import {getSettings,setSettings} from './settings.js';
let seeded=false;
export function ensureCmsSeed(){if(seeded)return;const page=key=>pageSeeds.find(p=>p.key===key)?.payload.sections;
 const standards=page('testing-standards').standards.items_standards,homeStandards=page('home').standards.items_standards;
 const services=page('services').listing.items_services,clients=page('clients').clients.items_clients,testimonials=page('clients').clients.items_testimonials;
 const categories=[{key:'paper&packaging',name:'Packaging Testing Instruments'},{key:'plastic&polymer',name:'Plastic & Polymer Testing'},{key:'polyFilms',name:'Poly Films & Laminates'},{key:'paint&plastic',name:'Paint & Plating Testing'}];
 for(const seed of pageSeeds)if(seed.key==='global')for(const block of Object.values(seed.payload.sections))for(const key of ['items_navLinks','items_quickLinks','items_productLinks'])if(block[key])block[key]=block[key].map((item,index)=>({...item,id:key+'-'+index,enabled:true,newTab:false,children:[]}));
 seedRecords([...pageSeeds,...products.map(p=>({kind:'product',key:p.cmsKey||p.id,slug:p.cmsSlug||p.id,title:p.name,payload:{...p,category_ids:[p.category],standard_ids:[],related_ids:[],featured:false,price_on_request:true,gallery:[],brochure:'',quote_prefill:p.name,image_alt:p.name}})),...categories.map(p=>({kind:'category',key:p.key,slug:p.key,title:p.name,payload:p})),...applications.map(p=>({kind:'application',key:p.id,slug:p.id,title:p.name,payload:p})),...standards.map((p,i)=>({kind:'standard',key:p.code,slug:p.code.toLowerCase(),title:p.name,payload:{...p,home_name:homeStandards[i]?.name,home_count:homeStandards[i]?.count}})),...services.map(p=>({kind:'service',key:p.link.split('/').pop(),slug:p.link.split('/').pop(),title:p.title,payload:{...p,body:page('service-'+p.link.split('/').pop()).detail[serviceBindings[p.link.split('/').pop()].paragraphs[0]],body_continued:page('service-'+p.link.split('/').pop()).detail[serviceBindings[p.link.split('/').pop()].paragraphs[1]]||'',detail_title:page('service-'+p.link.split('/').pop()).detail[serviceBindings[p.link.split('/').pop()].titleKey]}})),...clients.map((p,i)=>({kind:'client',key:'client-'+i,slug:'client-'+i,title:p.name,payload:p})),...testimonials.map((p,i)=>({kind:'testimonial',key:'testimonial-'+i,slug:'testimonial-'+i,title:p.company,payload:p})),...['privacy-policy','terms-of-service'].map(key=>({kind:'page',key,slug:key,title:key.replaceAll('-',' '),status:'draft',payload:{title:key.replaceAll('-',' '),body:'',seo:{noindex:true}}}))]);
 if(!Object.keys(getSettings('contact')).length)setSettings('contact',{address:'Plot No. 574, Aasharam Marg, Siddiq Nagar, Sihani Road, Ghaziabad 201001',phones:[{number:'+918595362719',display:'8595362719'},{number:'+918586962719',display:'8586962719'}],emails:['info@pakmoo.in'],whatsapp:'918595362719',whatsappMessage:'Hi, I need information about testing instruments',hours:'Mon – Sat: 9:00 AM – 6:00 PM (IST)'},null);
 if(!Object.keys(getSettings('seo')).length)setSettings('seo',{siteName:'PAKMOO Testing Instruments',titleTemplate:'%title% | PAKMOO Testing Instruments',defaultDescription:'Precision testing instruments and industry-standard laboratory solutions.',defaultOgImage:'',googleVerification:'',bingVerification:'',allowIndex:true,sitemapEnabled:true},null);
 seeded=true;
}
export function publicCmsSnapshot(){ensureCmsSeed();const pages=Object.fromEntries(listContent('page',true).map(row=>[row.key,row.payload]));const collections=Object.fromEntries(['product','category','application','standard','client','testimonial','service'].map(kind=>[kind,listContent(kind,true).map(row=>({...row.payload,_cmsId:row.id,_slug:row.slug,_key:row.key}))]));const settings=Object.fromEntries(['header','footer','contact','seo','schema'].map(scope=>[scope,getSettings(scope)]));return {pages,collections,settings};}
